# ============================================================================
# 2. CONFIGURATION
# ============================================================================

@dataclass(frozen=True)
class Settings:
    env: str
    host: str
    port: int
    secret_key: str
    database_path: Path
    upload_dir: Path
    max_glb_bytes: int
    token_ttl_seconds: int
    rate_limit_requests: int
    rate_limit_window_seconds: int

    @classmethod
    def from_env(cls, base_dir: Path | None = None) -> "Settings":
        root = base_dir or Path.cwd() / "vto_data"
        secret = os.getenv("VTO_SECRET_KEY") or secrets.token_hex(32)
        render_port = os.getenv("PORT")
        default_host = "0.0.0.0" if render_port else "127.0.0.1"
        default_port = render_port or "8000"
        return cls(
            env=os.getenv("VTO_ENV", "production" if render_port else "development"),
            host=os.getenv("VTO_HOST", default_host),
            port=int(os.getenv("VTO_PORT", default_port)),
            secret_key=secret,
            database_path=Path(os.getenv("VTO_DB_PATH", str(root / "vto.db"))),
            upload_dir=Path(os.getenv("VTO_UPLOAD_DIR", str(root / "uploads"))),
            max_glb_bytes=int(os.getenv("VTO_MAX_GLB_BYTES", str(15 * 1024 * 1024))),
            token_ttl_seconds=int(os.getenv("VTO_TOKEN_TTL_SECONDS", "86400")),
            rate_limit_requests=int(os.getenv("VTO_RATE_LIMIT_REQUESTS", "120")),
            rate_limit_window_seconds=int(os.getenv("VTO_RATE_LIMIT_WINDOW_SECONDS", "60")),
        )


# ============================================================================
# 3. DATABASE LAYER (SQLite WAL + Foreign Keys + Indexes)
# ============================================================================

SCHEMA_SQL = """
PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;

CREATE TABLE IF NOT EXISTS tenants (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    plan TEXT NOT NULL DEFAULT 'start' CHECK (plan IN ('start', 'business', 'scale')),
    monthly_quota INTEGER NOT NULL DEFAULT 3000,
    allowed_origins TEXT NOT NULL DEFAULT '[]',
    api_key_prefix TEXT NOT NULL,
    api_key_hash TEXT NOT NULL UNIQUE,
    is_active INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS users (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    email TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('admin', 'editor', 'viewer')),
    is_active INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS hairstyles (
    id TEXT PRIMARY KEY,
    tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    sku TEXT NOT NULL,
    name TEXT NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    tags_json TEXT NOT NULL DEFAULT '[]',
    model_url TEXT NOT NULL,
    calibration_json TEXT NOT NULL,
    is_active INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    UNIQUE (tenant_id, sku)
);

CREATE TABLE IF NOT EXISTS telemetry_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    event_type TEXT NOT NULL CHECK (event_type IN (
        'widget_open', 'tryon_applied', 'face_shape_detected', 'snapshot_saved', 'cta_click'
    )),
    sku TEXT,
    face_shape TEXT,
    session_id TEXT NOT NULL,
    origin TEXT,
    created_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_users_tenant ON users(tenant_id);
CREATE INDEX IF NOT EXISTS idx_hairstyles_tenant_active ON hairstyles(tenant_id, is_active);
CREATE INDEX IF NOT EXISTS idx_telemetry_tenant_created ON telemetry_events(tenant_id, created_at);
CREATE INDEX IF NOT EXISTS idx_telemetry_tenant_event ON telemetry_events(tenant_id, event_type);
"""


class Database:
    def __init__(self, db_path: Path) -> None:
        self.db_path = db_path
        self.db_path.parent.mkdir(parents=True, exist_ok=True)
        self.init_schema()

    def _connect(self) -> sqlite3.Connection:
        conn = sqlite3.connect(str(self.db_path), timeout=10.0)
        conn.row_factory = sqlite3.Row
        conn.execute("PRAGMA foreign_keys = ON;")
        return conn

    def init_schema(self) -> None:
        with self.transaction() as conn:
            conn.executescript(SCHEMA_SQL)

    @contextmanager
    def transaction(self) -> Iterator[sqlite3.Connection]:
        conn = self._connect()
        try:
            yield conn
            conn.commit()
        except Exception:
            conn.rollback()
            raise
        finally:
            conn.close()


# ============================================================================
# 4. SECURITY PRIMITIVES (Passwords, HMAC Tokens, RBAC, Rate Limit, GLB Check)
# ============================================================================

GLB_MAGIC = b"glTF"
GLB_VERSION_2 = 2


class SecurityError(Exception):
    def __init__(self, message: str, status_code: int = 401) -> None:
        super().__init__(message)
        self.message = message
        self.status_code = status_code


def hash_password(password: str) -> str:
    return generate_password_hash(password, method="pbkdf2:sha256:260000", salt_length=16)


def verify_password(password: str, password_hash: str) -> bool:
    return check_password_hash(password_hash, password)


def generate_api_key() -> tuple[str, str, str]:
    token = secrets.token_urlsafe(32)
    full_key = f"vto_live_{token}"
    prefix = full_key[:16]
    return full_key, prefix, hash_api_key(full_key)


def hash_api_key(api_key: str) -> str:
    return hashlib.sha256(api_key.encode("utf-8")).hexdigest()


def _b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def _b64url_decode(data: str) -> bytes:
    padding = "=" * (-len(data) % 4)
    return base64.urlsafe_b64decode(data + padding)


def create_access_token(payload: dict[str, Any], secret_key: str, ttl_seconds: int) -> str:
    header = {"alg": "HS256", "typ": "JWT"}
    now = int(time.time())
    body = {**payload, "iat": now, "exp": now + ttl_seconds}
    h_b64 = _b64url_encode(json.dumps(header, separators=(",", ":")).encode("utf-8"))
    b_b64 = _b64url_encode(json.dumps(body, separators=(",", ":")).encode("utf-8"))
    signing_input = f"{h_b64}.{b_b64}".encode("ascii")
    sig = hmac.new(secret_key.encode("utf-8"), signing_input, hashlib.sha256).digest()
    return f"{h_b64}.{b_b64}.{_b64url_encode(sig)}"


def verify_access_token(token: str, secret_key: str) -> dict[str, Any]:
    parts = token.split(".")
    if len(parts) != 3:
        raise SecurityError("Malformed authentication token.", 401)
    h_b64, b_b64, sig_b64 = parts
    signing_input = f"{h_b64}.{b_b64}".encode("ascii")
    expected_sig = hmac.new(secret_key.encode("utf-8"), signing_input, hashlib.sha256).digest()
    try:
        provided_sig = _b64url_decode(sig_b64)
    except Exception as exc:
        raise SecurityError("Invalid token encoding.", 401) from exc
    if not hmac.compare_digest(expected_sig, provided_sig):
        raise SecurityError("Invalid token signature.", 401)
    try:
        payload = json.loads(_b64url_decode(b_b64).decode("utf-8"))
    except Exception as exc:
        raise SecurityError("Invalid token payload.", 401) from exc
    if int(payload.get("exp", 0)) < int(time.time()):
        raise SecurityError("Token has expired.", 401)
    return payload


ROLE_PERMISSIONS: dict[str, set[str]] = {
    "admin": {"read", "write", "manage_users", "rotate_keys"},
    "editor": {"read", "write"},
    "viewer": {"read"},
}


def require_permission(role: str, permission: str) -> None:
    if permission not in ROLE_PERMISSIONS.get(role, set()):
        raise SecurityError(f"Role '{role}' lacks required permission '{permission}'.", 403)


def validate_glb_bytes(data: bytes, max_bytes: int) -> None:
    if not data:
        raise SecurityError("Uploaded file is empty.", 400)
    if len(data) > max_bytes:
        raise SecurityError(f"GLB file exceeds maximum allowed size ({max_bytes} bytes).", 413)
    if len(data) < 12:
        raise SecurityError("File is too small to be a valid GLB binary.", 400)
    magic, version, declared_length = struct.unpack("<4sII", data[:12])
    if magic != GLB_MAGIC:
        raise SecurityError("Invalid file signature: expected binary glTF (.glb).", 400)
    if version != GLB_VERSION_2:
        raise SecurityError(f"Unsupported glTF version {version}; version 2 required.", 400)
    if declared_length != len(data):
        raise SecurityError("Corrupted GLB header: declared length does not match file size.", 400)


@dataclass
class RateLimitResult:
    allowed: bool
    remaining: int
    reset_after: int


class SlidingWindowRateLimiter:
    def __init__(self, max_requests: int, window_seconds: int) -> None:
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self._hits: dict[str, deque[float]] = defaultdict(deque)
        self._lock = threading.Lock()

    def check(self, key: str) -> RateLimitResult:
        now = time.monotonic()
        cutoff = now - self.window_seconds
        with self._lock:
            bucket = self._hits[key]
            while bucket and bucket[0] < cutoff:
                bucket.popleft()
            if len(bucket) >= self.max_requests:
                reset_after = max(1, int(bucket[0] + self.window_seconds - now))
                return RateLimitResult(False, 0, reset_after)
            bucket.append(now)
            return RateLimitResult(True, self.max_requests - len(bucket), self.window_seconds)


# ============================================================================
# 5. VALIDATION SCHEMAS (Pydantic v2 + Stored XSS Sanitization)
# ============================================================================

SKU_RE = re.compile(r"^[a-z0-9][a-z0-9_-]{1,62}$")
EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
TAG_RE = re.compile(r"^[a-z0-9_-]{1,32}$")
SCRIPT_STYLE_BLOCK_RE = re.compile(r"<(script|style)\b[^>]*>.*?</\1>", re.IGNORECASE | re.DOTALL)
HTML_TAG_RE = re.compile(r"<[^>]*>")


def sanitize_text(value: str) -> str:
    without_blocks = SCRIPT_STYLE_BLOCK_RE.sub("", value)
    cleaned = HTML_TAG_RE.sub("", without_blocks).strip()
    return re.sub(r"\s+", " ", cleaned)


class CalibrationModel(BaseModel):
    model_config = ConfigDict(extra="forbid")
    x: float = Field(default=0.0, ge=-15.0, le=15.0)
    y: float = Field(default=2.2, ge=-15.0, le=15.0)
    z: float = Field(default=-4.2, ge=-20.0, le=10.0)
    scale: float = Field(default=1.0, ge=0.2, le=3.5)


class RegisterTenantRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")
    salon_name: str = Field(..., min_length=2, max_length=100)
    email: str = Field(..., min_length=5, max_length=160)
    password: str = Field(..., min_length=8, max_length=128)
    allowed_origins: list[str] = Field(default_factory=lambda: ["http://localhost:8000", "http://127.0.0.1:8000"])

    @field_validator("salon_name")
    @classmethod
    def clean_salon_name(cls, v: str) -> str:
        cleaned = sanitize_text(v)
        if len(cleaned) < 2:
            raise ValueError("Salon name must contain at least 2 valid characters.")
        return cleaned

    @field_validator("email")
    @classmethod
    def validate_email(cls, v: str) -> str:
        email = v.strip().lower()
        if not EMAIL_RE.match(email):
            raise ValueError("Invalid email address format.")
        return email

    @field_validator("allowed_origins")
    @classmethod
    def validate_origins(cls, origins: list[str]) -> list[str]:
        if len(origins) > 20:
            raise ValueError("At most 20 allowed origins are permitted.")
        cleaned: list[str] = []
        for origin in origins:
            o = origin.strip().rstrip("/")
            if not (o.startswith("https://") or o.startswith("http://localhost") or o.startswith("http://127.0.0.1")):
                raise ValueError(f"Origin must be https:// or localhost: {origin}")
            cleaned.append(o)
        return cleaned


class LoginRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")
    email: str = Field(..., min_length=5, max_length=160)
    password: str = Field(..., min_length=1, max_length=128)

    @field_validator("email")
    @classmethod
    def normalize_email(cls, v: str) -> str:
        return v.strip().lower()


class CreateUserRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")
    email: str = Field(..., min_length=5, max_length=160)
    password: str = Field(..., min_length=8, max_length=128)
    role: Literal["admin", "editor", "viewer"] = "viewer"

    @field_validator("email")
    @classmethod
    def validate_email(cls, v: str) -> str:
        email = v.strip().lower()
        if not EMAIL_RE.match(email):
            raise ValueError("Invalid email address format.")
        return email


class HairstyleCreateRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")
    sku: str = Field(..., min_length=2, max_length=63)
    name: str = Field(..., min_length=2, max_length=100)
    description: str = Field(default="", max_length=300)
    tags: list[str] = Field(default_factory=list, max_length=12)
    model_url: str = Field(..., min_length=1, max_length=500)
    calibration: CalibrationModel = Field(default_factory=CalibrationModel)

    @field_validator("sku")
    @classmethod
    def validate_sku(cls, v: str) -> str:
        sku = v.strip().lower()
        if not SKU_RE.match(sku):
            raise ValueError("SKU must match ^[a-z0-9][a-z0-9_-]{1,62}$")
        return sku

    @field_validator("name", "description")
    @classmethod
    def clean_strings(cls, v: str) -> str:
        return sanitize_text(v)

    @field_validator("tags")
    @classmethod
    def validate_tags(cls, tags: list[str]) -> list[str]:
        out = []
        for t in tags:
            val = t.strip().lower()
            if not TAG_RE.match(val):
                raise ValueError(f"Invalid tag format: {t}")
            out.append(val)
        return sorted(set(out))

    @field_validator("model_url")
    @classmethod
    def validate_model_url(cls, v: str) -> str:
        url = v.strip()
        if url.lower().startswith(("javascript:", "data:", "vbscript:")) or ".." in url:
            raise ValueError("Unsafe model_url.")
        if not (url.startswith("https://") or url.startswith("/") or url.startswith("./")):
            raise ValueError("model_url must be https:// or relative path.")
        return url


class HairstyleUpdateRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")
    name: Optional[str] = Field(default=None, min_length=2, max_length=100)
    description: Optional[str] = Field(default=None, max_length=300)
    tags: Optional[list[str]] = Field(default=None, max_length=12)
    model_url: Optional[str] = Field(default=None, min_length=1, max_length=500)
    calibration: Optional[CalibrationModel] = None
    is_active: Optional[bool] = None

    @field_validator("name", "description")
    @classmethod
    def clean_opt_strings(cls, v: Optional[str]) -> Optional[str]:
        return sanitize_text(v) if v is not None else None

    @field_validator("tags")
    @classmethod
    def validate_opt_tags(cls, tags: Optional[list[str]]) -> Optional[list[str]]:
        if tags is None:
            return None
        for t in tags:
            if not TAG_RE.match(t.strip().lower()):
                raise ValueError(f"Invalid tag format: {t}")
        return sorted(set(t.strip().lower() for t in tags))

    @field_validator("model_url")
    @classmethod
    def validate_opt_url(cls, v: Optional[str]) -> Optional[str]:
        if v is None:
            return None
        url = v.strip()
        if url.lower().startswith(("javascript:", "data:", "vbscript:")) or ".." in url:
            raise ValueError("Unsafe model_url.")
        if not (url.startswith("https://") or url.startswith("/") or url.startswith("./")):
            raise ValueError("model_url must be https:// or relative path.")
        return url


class TelemetryEventRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")
    event_type: Literal["widget_open", "tryon_applied", "face_shape_detected", "snapshot_saved", "cta_click"]
    sku: Optional[str] = Field(default=None, max_length=64)
    face_shape: Optional[Literal["oval", "round", "square", "heart", "oblong", "diamond"]] = None
    session_id: str = Field(..., min_length=8, max_length=64)

    @field_validator("sku")
    @classmethod
    def validate_sku(cls, v: Optional[str]) -> Optional[str]:
        if v is None or v == "":
            return None
        sku = v.strip().lower()
        if not SKU_RE.match(sku):
            raise ValueError("Invalid SKU.")
        return sku


