# 6. BUSINESS LOGIC LAYER & AUTO-SEED
# ============================================================================

def utc_now_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


class AppError(Exception):
    def __init__(self, message: str, status_code: int = 400, code: str = "bad_request") -> None:
        super().__init__(message)
        self.message = message
        self.status_code = status_code
        self.code = code


class VTOService:
    def __init__(self, db: Database, settings: Settings) -> None:
        self.db = db
        self.settings = settings
        self.settings.upload_dir.mkdir(parents=True, exist_ok=True)

    def register_tenant(self, req: RegisterTenantRequest) -> dict[str, Any]:
        tenant_id = f"tnt_{uuid.uuid4().hex[:12]}"
        user_id = f"usr_{uuid.uuid4().hex[:12]}"
        api_key, key_prefix, key_hash = generate_api_key()
        now = utc_now_iso()

        try:
            with self.db.transaction() as conn:
                conn.execute(
                    """
                    INSERT INTO tenants (id, name, plan, monthly_quota, allowed_origins, api_key_prefix, api_key_hash, created_at)
                    VALUES (?, ?, 'start', 3000, ?, ?, ?, ?)
                    """,
                    (tenant_id, req.salon_name, json.dumps(req.allowed_origins), key_prefix, key_hash, now),
                )
                conn.execute(
                    """
                    INSERT INTO users (id, tenant_id, email, password_hash, role, created_at)
                    VALUES (?, ?, ?, ?, 'admin', ?)
                    """,
                    (user_id, tenant_id, req.email, hash_password(req.password), now),
                )
        except sqlite3.IntegrityError as exc:
            raise AppError("An account with this email already exists.", 409, "email_exists") from exc

        token = create_access_token(
            {"sub": user_id, "tenant_id": tenant_id, "role": "admin", "email": req.email},
            self.settings.secret_key,
            self.settings.token_ttl_seconds,
        )
        return {
            "access_token": token,
            "token_type": "Bearer",
            "tenant": {
                "id": tenant_id,
                "name": req.salon_name,
                "plan": "start",
                "allowed_origins": req.allowed_origins,
                "api_key_prefix": key_prefix,
                "api_key": api_key,
            },
            "user": {"id": user_id, "email": req.email, "role": "admin"},
        }

    def login(self, req: LoginRequest) -> dict[str, Any]:
        with self.db.transaction() as conn:
            row = conn.execute(
                """
                SELECT u.id, u.tenant_id, u.email, u.password_hash, u.role, u.is_active,
                       t.name AS tenant_name, t.plan, t.api_key_prefix, t.allowed_origins
                FROM users u
                JOIN tenants t ON t.id = u.tenant_id
                WHERE u.email = ? AND t.is_active = 1
                """,
                (req.email,),
            ).fetchone()

        if not row or not row["is_active"] or not verify_password(req.password, row["password_hash"]):
            raise SecurityError("Invalid email or password.", 401)

        token = create_access_token(
            {"sub": row["id"], "tenant_id": row["tenant_id"], "role": row["role"], "email": row["email"]},
            self.settings.secret_key,
            self.settings.token_ttl_seconds,
        )
        return {
            "access_token": token,
            "token_type": "Bearer",
            "user": {"id": row["id"], "email": row["email"], "role": row["role"]},
            "tenant": {
                "id": row["tenant_id"],
                "name": row["tenant_name"],
                "plan": row["plan"],
                "api_key_prefix": row["api_key_prefix"],
                "allowed_origins": json.loads(row["allowed_origins"]),
            },
        }

    def create_user(self, tenant_id: str, req: CreateUserRequest) -> dict[str, Any]:
        user_id = f"usr_{uuid.uuid4().hex[:12]}"
        now = utc_now_iso()
        try:
            with self.db.transaction() as conn:
                conn.execute(
                    "INSERT INTO users (id, tenant_id, email, password_hash, role, created_at) VALUES (?, ?, ?, ?, ?, ?)",
                    (user_id, tenant_id, req.email, hash_password(req.password), req.role, now),
                )
        except sqlite3.IntegrityError as exc:
            raise AppError("User email already exists.", 409, "email_exists") from exc
        return {"id": user_id, "email": req.email, "role": req.role, "created_at": now}

    def rotate_api_key(self, tenant_id: str) -> dict[str, Any]:
        api_key, prefix, key_hash = generate_api_key()
        with self.db.transaction() as conn:
            cur = conn.execute(
                "UPDATE tenants SET api_key_prefix = ?, api_key_hash = ? WHERE id = ?",
                (prefix, key_hash, tenant_id),
            )
            if cur.rowcount == 0:
                raise AppError("Tenant not found.", 404, "not_found")
        return {"api_key": api_key, "api_key_prefix": prefix}

    def authenticate_widget_key(self, api_key: str, origin: str | None) -> dict[str, Any]:
        if not api_key:
            raise SecurityError("Missing API key.", 401)
        key_hash = hash_api_key(api_key)
        with self.db.transaction() as conn:
            tenant = conn.execute(
                "SELECT id, name, plan, monthly_quota, allowed_origins, is_active FROM tenants WHERE api_key_hash = ?",
                (key_hash,),
            ).fetchone()
        if not tenant or not tenant["is_active"]:
            raise SecurityError("Invalid or revoked API key.", 401)

        allowed = json.loads(tenant["allowed_origins"])
        if origin:
            normalized = origin.strip().rstrip("/")
            if allowed and normalized not in allowed:
                raise SecurityError(f"Origin '{normalized}' is not authorized for this API key.", 403)

        return {
            "id": tenant["id"],
            "name": tenant["name"],
            "plan": tenant["plan"],
            "monthly_quota": tenant["monthly_quota"],
            "allowed_origins": allowed,
        }

    @staticmethod
    def _serialize_hairstyle(row: sqlite3.Row) -> dict[str, Any]:
        return {
            "id": row["id"],
            "sku": row["sku"],
            "name": row["name"],
            "description": row["description"],
            "tags": json.loads(row["tags_json"]),
            "model_url": row["model_url"],
            "calibration": json.loads(row["calibration_json"]),
            "is_active": bool(row["is_active"]),
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
        }

    def list_hairstyles(self, tenant_id: str, only_active: bool = False) -> list[dict[str, Any]]:
        query = "SELECT * FROM hairstyles WHERE tenant_id = ?"
        if only_active:
            query += " AND is_active = 1"
        query += " ORDER BY created_at ASC"
        with self.db.transaction() as conn:
            rows = conn.execute(query, (tenant_id,)).fetchall()
        return [self._serialize_hairstyle(r) for r in rows]

    def create_hairstyle(self, tenant_id: str, req: HairstyleCreateRequest) -> dict[str, Any]:
        item_id = f"hst_{uuid.uuid4().hex[:12]}"
        now = utc_now_iso()
        try:
            with self.db.transaction() as conn:
                conn.execute(
                    """
                    INSERT INTO hairstyles (
                        id, tenant_id, sku, name, description, tags_json, model_url, calibration_json, created_at, updated_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        item_id, tenant_id, req.sku, req.name, req.description,
                        json.dumps(req.tags), req.model_url, json.dumps(req.calibration.model_dump()), now, now,
                    ),
                )
                row = conn.execute("SELECT * FROM hairstyles WHERE id = ?", (item_id,)).fetchone()
        except sqlite3.IntegrityError as exc:
            raise AppError(f"SKU '{req.sku}' already exists for this salon.", 409, "duplicate_sku") from exc
        return self._serialize_hairstyle(row)

    def update_hairstyle(self, tenant_id: str, sku: str, req: HairstyleUpdateRequest) -> dict[str, Any]:
        updates: list[str] = []
        params: list[Any] = []
        if req.name is not None:
            updates.append("name = ?")
            params.append(req.name)
        if req.description is not None:
            updates.append("description = ?")
            params.append(req.description)
        if req.tags is not None:
            updates.append("tags_json = ?")
            params.append(json.dumps(req.tags))
        if req.model_url is not None:
            updates.append("model_url = ?")
            params.append(req.model_url)
        if req.calibration is not None:
            updates.append("calibration_json = ?")
            params.append(json.dumps(req.calibration.model_dump()))
        if req.is_active is not None:
            updates.append("is_active = ?")
            params.append(1 if req.is_active else 0)
        if not updates:
            raise AppError("No fields provided for update.", 400, "empty_update")

        updates.append("updated_at = ?")
        params.append(utc_now_iso())
        params.extend([tenant_id, sku.lower()])

        with self.db.transaction() as conn:
            cur = conn.execute(
                f"UPDATE hairstyles SET {', '.join(updates)} WHERE tenant_id = ? AND sku = ?",
                tuple(params),
            )
            if cur.rowcount == 0:
                raise AppError("Hairstyle SKU not found.", 404, "not_found")
            row = conn.execute(
                "SELECT * FROM hairstyles WHERE tenant_id = ? AND sku = ?",
                (tenant_id, sku.lower()),
            ).fetchone()
        return self._serialize_hairstyle(row)

    def delete_hairstyle(self, tenant_id: str, sku: str) -> None:
        with self.db.transaction() as conn:
            cur = conn.execute(
                "DELETE FROM hairstyles WHERE tenant_id = ? AND sku = ?",
                (tenant_id, sku.lower()),
            )
            if cur.rowcount == 0:
                raise AppError("Hairstyle SKU not found.", 404, "not_found")

    def save_glb_upload(self, tenant_id: str, data: bytes) -> dict[str, Any]:
        validate_glb_bytes(data, self.settings.max_glb_bytes)
        tenant_dir = self.settings.upload_dir / tenant_id
        tenant_dir.mkdir(parents=True, exist_ok=True)
        filename = f"{uuid.uuid4().hex}.glb"
        (tenant_dir / filename).write_bytes(data)
        return {"filename": filename, "size_bytes": len(data), "model_url": f"/uploads/{tenant_id}/{filename}"}

    def resolve_upload_path(self, tenant_id: str, filename: str) -> Path:
        if not filename.endswith(".glb") or "/" in filename or "\\" in filename or ".." in filename:
            raise SecurityError("Invalid asset path.", 400)
        if "/" in tenant_id or "\\" in tenant_id or ".." in tenant_id:
            raise SecurityError("Invalid tenant path.", 400)
        base = self.settings.upload_dir.resolve()
        target = (base / tenant_id / filename).resolve()
        if base not in target.parents or not target.is_file():
            raise AppError("Asset not found.", 404, "not_found")
        return target

    def record_telemetry(self, tenant_id: str, req: TelemetryEventRequest, origin: str | None) -> None:
        with self.db.transaction() as conn:
            conn.execute(
                """
                INSERT INTO telemetry_events (tenant_id, event_type, sku, face_shape, session_id, origin, created_at)
                VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                (tenant_id, req.event_type, req.sku, req.face_shape, req.session_id, origin, utc_now_iso()),
            )

    def get_analytics(self, tenant_id: str) -> dict[str, Any]:
        with self.db.transaction() as conn:
            counts = {
                row["event_type"]: row["cnt"]
                for row in conn.execute(
                    "SELECT event_type, COUNT(*) AS cnt FROM telemetry_events WHERE tenant_id = ? GROUP BY event_type",
                    (tenant_id,),
                ).fetchall()
            }
            unique_sessions = conn.execute(
                "SELECT COUNT(DISTINCT session_id) AS cnt FROM telemetry_events WHERE tenant_id = ?",
                (tenant_id,),
            ).fetchone()["cnt"]
            top_skus = [
                {"sku": row["sku"], "tryons": row["cnt"]}
                for row in conn.execute(
                    """
                    SELECT sku, COUNT(*) AS cnt FROM telemetry_events
                    WHERE tenant_id = ? AND event_type = 'tryon_applied' AND sku IS NOT NULL
                    GROUP BY sku ORDER BY cnt DESC LIMIT 10
                    """,
                    (tenant_id,),
                ).fetchall()
            ]
            face_shapes = {
                row["face_shape"]: row["cnt"]
                for row in conn.execute(
                    """
                    SELECT face_shape, COUNT(*) AS cnt FROM telemetry_events
                    WHERE tenant_id = ? AND event_type = 'face_shape_detected' AND face_shape IS NOT NULL
                    GROUP BY face_shape
                    """,
                    (tenant_id,),
                ).fetchall()
            }

        opens = counts.get("widget_open", 0)
        tryons = counts.get("tryon_applied", 0)
        snapshots = counts.get("snapshot_saved", 0)
        cta_clicks = counts.get("cta_click", 0)

        return {
            "summary": {
                "unique_sessions": unique_sessions,
                "widget_opens": opens,
                "tryons_applied": tryons,
                "snapshots_saved": snapshots,
                "cta_clicks": cta_clicks,
                "snapshot_conversion_rate": round((snapshots / opens) * 100, 2) if opens else 0.0,
                "cta_conversion_rate": round((cta_clicks / opens) * 100, 2) if opens else 0.0,
            },
            "top_skus": top_skus,
            "face_shape_distribution": face_shapes,
        }


