# 8. BUILT-IN SELF-TEST SUITE (`python hair_vto_enterprise.py --test`)
# ============================================================================

def _make_valid_glb(payload: bytes = b'{"asset":{"version":"2.0"}} ') -> bytes:
    rem = len(payload) % 4
    if rem:
        payload += b" " * (4 - rem)
    chunk = struct.pack("<I4s", len(payload), b"JSON") + payload
    header = struct.pack("<4sII", b"glTF", 2, 12 + len(chunk))
    return header + chunk


class SingleFileEnterpriseTests(unittest.TestCase):
    def setUp(self) -> None:
        self.tmpdir = tempfile.TemporaryDirectory()
        tmp = Path(self.tmpdir.name)
        self.settings = Settings(
            env="test",
            host="127.0.0.1",
            port=8000,
            secret_key="single-file-test-secret-key-32-chars",
            database_path=tmp / "test.db",
            upload_dir=tmp / "uploads",
            max_glb_bytes=2 * 1024 * 1024,
            token_ttl_seconds=3600,
            rate_limit_requests=200,
            rate_limit_window_seconds=60,
        )
        self.app = VTOApplication(self.settings, auto_seed=True)
        self.client = Client(self.app)

    def tearDown(self) -> None:
        self.tmpdir.cleanup()

    def test_embedded_frontend_and_sdk_routes(self) -> None:
        r_idx = self.client.get("/")
        self.assertEqual(r_idx.status_code, 200)
        self.assertIn(b"sdk/widget.js", r_idx.data)

        r_dash = self.client.get("/dashboard.html")
        self.assertEqual(r_dash.status_code, 200)
        self.assertNotIn(b".innerHTML", r_dash.data)

        r_sdk = self.client.get("/sdk/widget.js")
        self.assertEqual(r_sdk.status_code, 200)
        self.assertIn("application/javascript", r_sdk.mimetype)
        self.assertIn(b"HairVTOWidget", r_sdk.data)

    def test_seeded_login_rbac_glb_upload_and_analytics(self) -> None:
        # Login with seeded admin
        login_res = self.client.post(
            "/api/v1/auth/login",
            json={"email": "admin@aura-salon.local", "password": "AuraSalon2026!"},
        )
        self.assertEqual(login_res.status_code, 200)
        token = login_res.get_json()["access_token"]
        auth = {"Authorization": f"Bearer {token}"}

        # Upload GLB
        glb = _make_valid_glb()
        up = self.client.post(
            "/api/v1/assets/upload",
            headers=auth,
            data={"file": (io.BytesIO(glb), "test.glb")},
            content_type="multipart/form-data",
        )
        self.assertEqual(up.status_code, 201)
        model_url = up.get_json()["model_url"]

        # Create SKU with XSS payload -> sanitized
        crt = self.client.post(
            "/api/v1/hairstyles",
            headers=auth,
            json={"sku": "new-cut", "name": "<script>x</script>New Cut", "model_url": model_url},
        )
        self.assertEqual(crt.status_code, 201)
        self.assertEqual(crt.get_json()["item"]["name"], "New Cut")

        # Widget config + telemetry with seeded API key
        api_key = self.app.seed_info["api_key"]
        cfg = self.client.get("/api/v1/widget/config", headers={"X-API-Key": api_key, "Origin": "http://localhost:8000"})
        self.assertEqual(cfg.status_code, 200)
        self.assertEqual(len(cfg.get_json()["catalog"]), 4)

        tel = self.client.post(
            "/api/v1/widget/telemetry",
            headers={"X-API-Key": api_key, "Origin": "http://localhost:8000"},
            json={"event_type": "widget_open", "session_id": "ses_987654321"},
        )
        self.assertEqual(tel.status_code, 202)

        an = self.client.get("/api/v1/analytics", headers=auth)
        self.assertEqual(an.status_code, 200)
        self.assertEqual(an.get_json()["summary"]["widget_opens"], 1)

    def test_embedded_sdk_js_structural_integrity(self) -> None:
        code = WIDGET_SDK_JS
        self.assertEqual(code.count(".innerHTML"), 1)
        in_single = in_double = in_tpl = escaped = False
        stack: list[str] = []
        pairs = {")": "(", "]": "[", "}": "{"}
        i = 0
        n = len(code)
        while i < n:
            ch = code[i]
            nxt = code[i + 1] if i + 1 < n else ""
            if not (in_single or in_double or in_tpl):
                if ch == "/" and nxt == "/":
                    while i < n and code[i] != "\n":
                        i += 1
                    continue
                if ch == "/" and nxt == "*":
                    i += 2
                    while i + 1 < n and not (code[i] == "*" and code[i + 1] == "/"):
                        i += 1
                    i += 2
                    continue
            if escaped:
                escaped = False
                i += 1
                continue
            if ch == "\\":
                escaped = True
                i += 1
                continue
            if ch == "'" and not in_double and not in_tpl:
                in_single = not in_single
            elif ch == '"' and not in_single and not in_tpl:
                in_double = not in_double
            elif ch == "`" and not in_single and not in_double:
                in_tpl = not in_tpl
            elif not (in_single or in_double or in_tpl):
                if ch in "([{":
                    stack.append(ch)
                elif ch in ")]}":
                    self.assertTrue(stack and stack[-1] == pairs[ch], f"Unbalanced {ch} at index {i}")
                    stack.pop()
            i += 1
        self.assertEqual(stack, [], f"Unclosed delimiters: {stack}")


def main() -> None:
    if "--test" in sys.argv:
        suite = unittest.defaultTestLoader.loadTestsFromTestCase(SingleFileEnterpriseTests)
        runner = unittest.TextTestRunner(verbosity=2)
        result = runner.run(suite)
        sys.exit(0 if result.wasSuccessful() else 1)

    cfg = Settings.from_env()
    app = VTOApplication(cfg, auto_seed=True)
    logger.info("==========================================================")
    logger.info("Enterprise Hair VTO Platform running at http://%s:%d", cfg.host, cfg.port)
    logger.info("Storefront Demo : http://%s:%d/", cfg.host, cfg.port)
    logger.info("B2B Dashboard   : http://%s:%d/dashboard.html", cfg.host, cfg.port)
    if app.seed_info.get("status") == "seeded":
        logger.info("Demo Admin Login: %s / %s", app.seed_info["admin_email"], app.seed_info["admin_password"])
        logger.info("Demo Widget Key : %s", app.seed_info["api_key"])
    logger.info("==========================================================")
    run_simple(cfg.host, cfg.port, app, use_reloader=False, threaded=True)


if __name__ == "__main__":
    main()
